	/**
	 * Check if it is after a specific time in a given zip code
	 */
	static isAfterCutOffTimeInZipCode(zip, dateStr, cutoffTimeStr) {
		// Logger.info(`${this.NAME} > isAfterCutOffTimeInZipCode`);

		const zipData = this.getDomesticZipData(zip);
		const dateParts = dateStr.split('-');

		if (zipData && dateParts.length === 3 && cutoffTimeStr.length === 4) {
			const timezone = zipData.timezone;

			// Get the current time in the timezone
			const time = new Date().toLocaleString('en-US', { timeZone: timezone });
			const currentTime = new Date(time);

			// Cast the cutoffTimeStr to a number
			const cutoffTime = new Date(time);
			cutoffTime.setFullYear(dateParts[0]);
			cutoffTime.setMonth(dateParts[1] - 1);
			cutoffTime.setDate(dateParts[2]);
			var cutoffHours = cutoffTimeStr.substring(0, 2);
			cutoffTime.setHours(cutoffHours);
			var cutoffMinutes = cutoffTimeStr.substring(cutoffTimeStr.length - 2);
			cutoffTime.setMinutes(cutoffMinutes);
			cutoffTime.setSeconds(0);

			// console.log(currentTime, cutoffTime);

			if (currentTime > cutoffTime) {
				return true;
			}

		}

		return false;
	}

	/**
	 * Get date object for a string, in the timezone of a given zip code
	 */
	static getDateObjectForZipCode(zip, dateStr) {
		// Logger.info(`${this.NAME} > getDateObjectForZipCode`);

		const zipData = this.getDomesticZipData(zip);

		const date = new Date(dateStr);
		if (isNaN(date)) {
			return 'Invalid date';
		}

		const year = date.getFullYear();
		const month = (date.getMonth() + 1).toString().padStart(2, '0');
		const day = date.getDate().toString().padStart(2, '0');

		const formattedDate = `${year}-${month}-${day}`;

		const dateParts = formattedDate.split('-');

		if (zipData && dateParts.length === 3) {
			const timezone = zipData.timezone;

			// Get the current time in the timezone
			const time = new Date().toLocaleString('en-US', { timeZone: timezone });
			const currentTime = new Date(time);
			currentTime.setFullYear(dateParts[0]);
			currentTime.setMonth(dateParts[1] - 1);
			currentTime.setDate(dateParts[2]);
			currentTime.setHours(0);
			currentTime.setMinutes(0);
			currentTime.setSeconds(0);

			return currentTime;
		}

		return null;
	}

	/**
	 * Get domestic zip data
	 */
	static getDomesticZipData(zip) {

		// Logger.info(`${this.NAME} > getDomesticZipData`);

		zip = parseInt(zip);

		// Check in domestic zip data JSON
		const data = domesticZipData.find(item => item.zipcode === zip);
		if (data) {
			return data;
		}

		return null;
	}

	/**
	 * Get timezone for zip code
	 */
	static getTimezoneForZipCode(zip) {
		Logger.info(`${this.NAME} > getTimezoneForZip > zip: ${zip}`);

		const data = this.getDomesticZipData(zip);
		if (data) {
			return data.timezone;
		}

		return null;
	}

	/**
		* Get flex shipping dates for zip code
		* @param {string} zip - Zip code
		* @returns {array} - Array of flex shipping dates
		*/
	static getFlexShippingDatesForZipCode(zip) {

		const holidaysArray = [];

		for (const holiday of window.pdpFlexShippingDates) {

			// Check if zip code is in the range of zip codes for this holiday
			if (holiday.zips.length > 0 && !holiday.zips.includes(parseInt(zip))) {
				console.log('Zip code not in range for holiday', holiday.holiday_name, zip, holiday.zips);
				continue;
			}

			// Check if zip code is in the excluded range of zip codes for this holiday
			if (holiday.excluded_zips.length > 0 && holiday.excluded_zips.includes(parseInt(zip))) {
				console.log('Zip code excluded from holiday', holiday.holiday_name, zip, holiday.excluded_zips);
				continue;
			}

			holidaysArray.push({
				"date": holiday.day_of_holiday,
				"holiday_name": holiday.holiday_name,
				"text": holiday.text
			});

			// Check how many days prior to holiday to highlight
			let flex_days_prior = Number(holiday.flex_days_prior);
			if (flex_days_prior > 0) {
				for (let i = 1; i <= flex_days_prior; i++) {
					const holiday_date = new Date(holiday.day_of_holiday);
					let prior_day = new Date(holiday_date);
					prior_day.setDate(holiday_date.getDate() + -i);
					holidaysArray.push({
						"date": prior_day.toISOString().slice(0, 10),
						"holiday_name": holiday.holiday_name,
						"text": holiday.text
					});
				}
			}

			// check how many days after the holiday to highlight
			let flex_days_post = Number(holiday.flex_days_post);
			if (flex_days_post > 0) {
				for (let i = 1; i <= flex_days_post; i++) {
					const holiday_date = new Date(holiday.day_of_holiday);
					let post_day = new Date(holiday_date);
					post_day.setDate(holiday_date.getDate() + i);
					holidaysArray.push({
						"date": post_day.toISOString().slice(0, 10),
						"holiday_name": holiday.holiday_name,
						"text": holiday.text
					});
				}
			}
		}

		return holidaysArray;
	}

