	static getRulesForPageByZipCode(pageRules, zipCode) {
		console.log('Getting Rules for Page by Zip Code', zipCode);

		let rulesPayload = {
			calendar: {
				disabledDates: [],
			},
			rules: [],
		};

		console.log(window.globalZipCodeRules);

		// 1. Get all the zip code rules for this page, regardless of the zip code
		// that the customer is in
		const allRulesForProduct = window.globalZipCodeRules.filter(rule => pageRules.includes(rule.rule));
		console.log(`All Rules for Page`, allRulesForProduct);

		// 2. Filter the rules down to the ones that apply to the customer's zip code
		// If the zip code field is empty, it is assumed that the rule applies to all zip codes
		// If the zip code is in the excluded_zips array, the rule does not apply
		const rulesForCustomerZip = allRulesForProduct.filter(rule => (rule.zips.length == 0 || rule.zips.includes(parseInt(zipCode))) && !rule.excluded_zips.includes(parseInt(zipCode)));
		console.log(`Rules for Customer Zip`, rulesForCustomerZip);


		// 3. If there are rules that apply to the customer's zip code, add them to the payload
		if (rulesForCustomerZip.length > 0) {
			rulesPayload.rules = rulesForCustomerZip;
		}

		return rulesPayload;
	}

